"""Read the supplied original's sleeping bomb leaf poses; never execute it."""
from pathlib import Path
from inspect_original import Original


def literal(value):
    number = format(value, '.6g')
    return number + ('.0f' if '.' not in number and 'e' not in number else 'f')


def main():
    original = Original()
    lines = [
        '// Generated by game/tools/import_bomb_visual.py from the supplied original.',
        '// Bomb.refreshV2SleepLeafPosByIdxFrame: 90 poses at 60 Hz, six petals.',
        '#pragma once',
        '#include "engine/core/geometry/vector2.h"',
        '#include <algorithm>',
        '#include <array>',
        '#include <cmath>',
        'namespace game::play {',
        'struct BombLeafPose {elysia::core::Vector2 offset;float rotation;};',
        '// ARM table at 0x19e8e0; converted from local Y-up to centered Y-down.',
        'inline constexpr std::array<std::array<BombLeafPose,6>,90> kBombSleepingLeaves{{',
    ]
    for frame in range(90):
        lines.append('    {{')
        for part in range(6):
            x, y, rotation = original.unpack('<3f', 0x19e8e0 + (frame * 6 + part) * 12)
            lines.append('        {{' + literal(x) + ',' + literal(-y) + '},' + literal(rotation) + '},')
        lines.append('    }},')
    lines.extend([
        '}};',
        'inline const std::array<BombLeafPose,6>& bomb_sleeping_pose(double seconds) {',
        '    const auto frame=static_cast<std::size_t>(std::floor(std::fmod(std::max(0.,seconds)*60.,90.)));',
        '    return kBombSleepingLeaves[frame];',
        '}',
        '}',
    ])
    target = Path(__file__).resolve().parents[1] / 'gameplay/bomb_visual.h'
    target.write_text('\n'.join(lines) + '\n', encoding='utf8')
    print(target)


if __name__ == '__main__':
    main()
